contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will call buy which is payable when baseToken == address(0). To keep general, accept an etherAmount
    // and pass it into c.buy{value: etherAmount}(...). The test observes pre/post virtual reserves and ensures
    // the expected invariant when the call does not revert.
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proof, bool[] calldata flags, uint256 etherAmount) public payable {
        // Precondition: sizes must match for inputs the helper expects. If mismatched, we can't form the MerkleMultiProof.
        require(tokenIds.length == tokenWeights.length, "len");

        // Build MerkleMultiProof struct in memory
        C.MerkleMultiProof memory mp;
        mp.proof = proof;
        mp.flags = flags;

        // Read pre-state via public getters
        uint128 preVirtualBase = c.virtualBaseTokenReserves();
        uint128 preVirtualNft = c.virtualNftReserves();
        uint256 preBalance = address(c).balance;

        // Try to call buy. We must pass etherAmount; ensure this contract has enough balance for the call
        if (etherAmount > 0) require(address(this).balance >= etherAmount, "fund");

        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        try c.buy{value: etherAmount}(tokenIds, tokenWeights, mp) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // Read post-state
        uint128 postVirtualBase = c.virtualBaseTokenReserves();
        uint128 postVirtualNft = c.virtualNftReserves();
        uint256 postBalance = address(c).balance;

        // Compute sum of weights in a way that won't underflow: use uint256
        uint256 sumWeights = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            sumWeights += tokenWeights[i];
        }

        // If call reverted, ensure no state change in those observable fields (virtual reserves and contract balance)
        // If call succeeded, assert the documented invariant from buy():
        // virtualBaseTokenReserves increases by (netInputAmount - feeAmount - protocolFeeAmount)
        // virtualNftReserves decreases by sumWeights
        // Also, when baseToken == address(0), the c balance should increase by netInputAmount (because netInputAmount paid into contract)
        // We express a single general assert combining both cases:
        assert(
            (reverted && postVirtualBase == preVirtualBase && postVirtualNft == preVirtualNft && postBalance == preBalance)
            ||
            (!reverted &&
                // check virtual base reserve change
                uint256(postVirtualBase) == uint256(preVirtualBase) + (netInputAmount - feeAmount - protocolFeeAmount)
                &&
                // check virtual nft reserve change (decrease)
                uint256(postVirtualNft) + sumWeights == uint256(preVirtualNft)
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Simpler test: call deposit and assert observable balance effects depending on baseToken type.
    function run(uint256[] calldata tokenIds, uint256 baseTokenAmount) public payable {
        // keep sizes reasonable to allow verification
        require(tokenIds.length <= 8, "too many tokens");

        // Ensure we have ETH available if we will send it to c.deposit
        if (baseTokenAmount > 0) require(address(this).balance >= baseTokenAmount, "funds");

        // Observe pre-state: pool's ether balance and virtualBaseTokenReserves
        uint256 preEth = address(c).balance;
        uint128 preVirtualBase = c.virtualBaseTokenReserves();

        // Build calldata for MerkleMultiProof not needed by deposit; deposit takes tokenIds and baseTokenAmount
        bool reverted;
        try c.deposit(tokenIds, baseTokenAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 postEth = address(c).balance;
        uint128 postVirtualBase = c.virtualBaseTokenReserves();

        // Single simple general assertion:
        // If call reverted then observable ETH balance and virtualBaseTokenReserves must be unchanged.
        // If not reverted then either baseToken == address(0) and contract ETH balance increased exactly by baseTokenAmount,
        // or baseToken != address(0) and ETH balance unchanged (since ERC20 transferred instead) and virtualBaseTokenReserves is unchanged by deposit.
        // We cannot read ERC20 balances here, so we check ETH movement or its absence and that virtual reserves didn't change when ERC20 used.
        assert(
            (reverted && postEth == preEth && postVirtualBase == preVirtualBase)
            ||
            (!reverted && (
                // case: pool uses native ETH -> observable ETH increase by baseTokenAmount
                (c.baseToken() == address(0) && postEth == preEth + baseTokenAmount)
                ||
                // case: pool uses ERC20 -> ETH shouldn't change and virtualBaseTokenReserves remains same (deposit doesn't alter virtual reserves)
                (c.baseToken() != address(0) && postEth == preEth && postVirtualBase == preVirtualBase)
            ))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single-call property: setFeeRate should only accept values <= 5000; if accepted feeRate getter equals input
    function run(uint16 newFeeRate) public payable {
        // Keep domain small for SMT solving
        require(newFeeRate <= 10000);

        uint256 preBalance = address(c).balance;

        bool reverted;
        try c.setFeeRate(newFeeRate) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint16 postFeeRate = c.feeRate();
        uint256 postBalance = address(c).balance;

        // General rule:
        // - If call reverted then newFeeRate must be > 5000 (the contract enforces FeeRateTooHigh)
        // - If call did not revert then c.feeRate() equals newFeeRate and c's ETH balance is unchanged
        assert(
            (reverted && newFeeRate > 5000)
            ||
            (!reverted && postFeeRate == newFeeRate && postBalance == preBalance)
        );
    }

    receive() external payable {}
}
